<template>
  <section class="flex flex-col gap-10">
    <div class="w-full flex justify-between gap-4 flex-wrap">
      <h1 class="font-semibold text-2xl sm:text-3xl">Submitted Signature</h1>
      <Badge
        v-if="data && data.status && !isLoading && !error"
        class="col-span-2 justify-self-center text-nowrap"
        :variant="getSubmittedSignaturesBadge(data.status).variant"
        >{{ getSubmittedSignaturesBadge(data.status).label }}
      </Badge>
    </div>
    <AppLoader v-if="isLoading" subject="signature details" />
    <AppError v-else-if="error" title="Failed to load signature details" :error="error" />
    <AppEmpty v-else-if="!data" subject="signature details" />
    <div v-else class="flex flex-col gap-4">
      <GoBackButton subject="signatures" />
      <div class="flex flex-col gap-6 w-full">
        <Card>
          <CardContent class="flex flex-col gap-4">
            <h3 class="text-xl font-medium">
              {{ signatoryName }}
            </h3>
            <Alert v-if="data.error_details" :variant="getSubmittedSignatureError(data.error_details).variant">
              <component :is="getSubmittedSignatureError(data.error_details).icon" />
              <AlertTitle>{{ getSubmittedSignatureError(data.error_details).title }}</AlertTitle>
              <AlertDescription>{{ getSubmittedSignatureError(data.error_details).description }}</AlertDescription>
            </Alert>
            <Separator />
            <SignatureDetailsMain :data="data" />
            <Separator />
            <SignaturePreview
              :image-url="data.ballot_row_url"
              :ballot-page-id="data.ballot_page_id"
              :signature-id="route.params.id"
              button-label="Open Petition Page"
            />
            <Separator />
            <h3 class="text-xl font-medium">Submitted Information</h3>
            <template v-if="signatureForm">
              <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                <LabeledValue
                  v-for="(value, key) in signatureForm.formData"
                  :key="key"
                  :label="snakeCaseToCapitalizedCase(key)"
                  :value="value"
                />
              </div>
              <Separator />
              <template v-if="data.state_voter_id !== null || data.voter_region !== null">
                <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <LabeledValue
                    v-if="data.state_voter_id !== null"
                    label="State Voter ID"
                    :value="data.state_voter_id"
                  />
                  <LabeledValue v-if="data.voter_region !== null" label="Region" :value="data.voter_region" />
                </div>
                <Separator />
              </template>
              <template v-if="signatureForm.otherData && Object.keys(signatureForm.otherData).length > 0">
                <h3 class="text-lg font-medium">Additional Information</h3>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <LabeledValue
                    v-for="(value, key) in signatureForm.otherData"
                    :key="key"
                    :label="snakeCaseToCapitalizedCase(key.toString())"
                    :value="formatIfDateValue(value)"
                  />
                </div>
                <Separator />
              </template>
            </template>
            <AppEmpty v-else variant="table" subject="submitted information" />
            <div v-if="data.original_submitted" class="flex flex-col gap-4">
              <h3 class="text-xl font-medium">Original Signature</h3>
              <NuxtLink
                :to="{
                  name: 'verification-ballots-signatures-submitted-id',
                  params: { id: data.original_submitted.id },
                }"
              >
                <BallotsSignaturesListItem :item="data.original_submitted" />
              </NuxtLink>
            </div>
            <h3 class="text-xl font-medium">Valid Signature</h3>
            <NuxtLink
              v-if="data.valid_signature"
              :to="{ name: 'verification-ballots-signatures-valid-id', params: { id: data.valid_signature.id } }"
            >
              <BallotsSignaturesListItem :item="data.valid_signature" />
            </NuxtLink>
            <AppEmpty v-else subject="valid signature" variant="table" />
          </CardContent>
        </Card>
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import { getSubmittedSignatureDetails } from '~/client';
import { getSubmittedSignaturesBadge } from '~/constants/verifications/submittedSignatureStatus';
import { getSubmittedSignatureError } from '~/constants/verifications/signatureErrors';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'signature',
});

const route = useRoute('verification-ballots-signatures-submitted-id');

const { data, isLoading, error } = useQuery({
  key: () => ['verification.ballot.submitted-signature', route.params.id],
  query: () =>
    getSubmittedSignatureDetails({ composable: '$fetch', path: { submitted_signature_id: route.params.id } }),
  enabled: () => !!route.params.id,
});

const signatoryName = computed(() => {
  const signatory = data.value?.valid_signature?.signatory;
  if (signatory) {
    return [signatory.first_name, signatory.last_name].filter(Boolean).join(' ');
  }
  const formData = signatureForm.value?.formData;
  if (formData) {
    return [formData.first_name, formData.last_name].filter(Boolean).join(' ');
  }
  return '';
});

const signatureForm = computed(() => {
  if (!data.value?.signatory_form) return null;
  const { signed_date, other_data, ...rest } = data.value.signatory_form;
  return { formData: rest, otherData: other_data };
});

const { timezone } = useUserRole();

function formatIfDateValue(value: string) {
  const dateType = detectDateType(value);
  if (dateType === 'invalid') return value;
  return formatDateBasedOnType(value, timezone.value);
}
</script>
